const nombreDe = (f, i = 0) => f.nombre || `foto-${i + 1}.jpg`;
const fmtPeso = (b) => (!b ? null : b > 1048576 ? `${(b / 1048576).toFixed(2)} MB` : `${Math.round(b / 1024)} KB`);

/* ---------- Lector EXIF (JPG, y RAW basados en TIFF: CR2, NEF, ARW, DNG…) ---------- */
const TAGS_EXIF = { 0x010f: 'marca', 0x0110: 'modelo', 0x0131: 'software', 0x829a: 'exposicion', 0x829d: 'apertura', 0x8827: 'iso', 0x9003: 'fecha', 0x920a: 'focal', 0xa434: 'lente' };
const TAM_TIPO = { 1: 1, 2: 1, 3: 2, 4: 4, 5: 8, 7: 1, 9: 4, 10: 8 };

function buscarTiff(u8, v) {
  const n = u8.length;
  const cab = v.getUint16(0);
  if (cab === 0x4949 || cab === 0x4d4d) return 0;
  if (cab === 0xffd8) {
    let p = 2;
    while (p + 10 < n && u8[p] === 0xff) {
      const m = u8[p + 1];
      if (m === 0xda || m === 0xd9) break;
      if (m === 0xe1 && u8[p + 4] === 0x45 && u8[p + 5] === 0x78) return p + 10;
      p += 2 + ((u8[p + 2] << 8) | u8[p + 3]);
    }
  }
  const lim = Math.min(n - 8, 262144);
  for (let i = 0; i < lim; i++) {
    const w = v.getUint32(i);
    if (w === 0x49492a00 || w === 0x4d4d002a) return i;
  }
  return -1;
}

function valorTag(v, e, little, tiff) {
  const tipo = v.getUint16(e + 2, little);
  const cuenta = v.getUint32(e + 4, little);
  const tam = (TAM_TIPO[tipo] || 1) * cuenta;
  const off = tam <= 4 ? e + 8 : tiff + v.getUint32(e + 8, little);
  if (tipo === 2) {
    let s = '';
    for (let i = 0; i < Math.min(cuenta, 120); i++) { const c = v.getUint8(off + i); if (!c) break; s += String.fromCharCode(c); }
    return s.trim();
  }
  if (tipo === 3) return v.getUint16(off, little);
  if (tipo === 4) return v.getUint32(off, little);
  if (tipo === 5) { const d = v.getUint32(off + 4, little); return d ? v.getUint32(off, little) / d : 0; }
  return null;
}

function leerIfd(v, tiff, ifd, little, out, seguir) {
  const n = v.getUint16(ifd, little);
  for (let i = 0; i < n && i < 400; i++) {
    const e = ifd + 2 + i * 12;
    const tag = v.getUint16(e, little);
    if (tag === 0x8769 && seguir) leerIfd(v, tiff, tiff + v.getUint32(e + 8, little), little, out, false);
    else if (TAGS_EXIF[tag]) out[TAGS_EXIF[tag]] = valorTag(v, e, little, tiff);
  }
}

function leerExif(u8) {
  const out = {};
  try {
    const v = new DataView(u8.buffer, u8.byteOffset, u8.byteLength);
    const tiff = buscarTiff(u8, v);
    if (tiff < 0) return out;
    const little = v.getUint16(tiff) === 0x4949;
    leerIfd(v, tiff, tiff + v.getUint32(tiff + 4, little), little, out, true);
  } catch (err) { /* sin EXIF legible */ }
  if (out.exposicion) out.exposicion = out.exposicion < 1 ? `1/${Math.round(1 / out.exposicion)} s` : `${out.exposicion} s`;
  if (out.apertura) out.apertura = `f/${Number(out.apertura).toFixed(1)}`;
  if (out.focal) out.focal = `${Math.round(out.focal)} mm`;
  if (out.iso) out.iso = `ISO ${out.iso}`;
  if (out.fecha) out.fecha = out.fecha.replace(/^(\d{4}):(\d{2}):(\d{2})/, '$3/$2/$1');
  return out;
}

const datosMeta = (file, u8) => ({
  peso: file.size,
  tipo: file.type || `${(file.name.split('.').pop() || '').toUpperCase()} (RAW)`,
  modificado: file.lastModified,
  exif: leerExif(u8),
});

function filasMeta(f, i) {
  const m = f.meta || {};
  const e = m.exif || {};
  return [
    ['Archivo', nombreDe(f, i)],
    ['Formato', m.tipo],
    ['Peso', fmtPeso(m.peso)],
    [f.raw ? 'Dimensiones (vista previa)' : 'Dimensiones', f.ancho ? `${f.ancho} × ${f.alto} px` : null],
    ['Resolución', f.ancho ? `${((f.ancho * f.alto) / 1e6).toFixed(1)} MP` : null],
    ['Orientación', f.forma && ETIQUETA_FORMA[f.forma]],
    ['Fecha de captura', e.fecha],
    ['Cámara', [e.marca, e.modelo].filter(Boolean).join(' ')],
    ['Lente', e.lente],
    ['Distancia focal', e.focal],
    ['Apertura', e.apertura],
    ['Velocidad', e.exposicion],
    ['ISO', e.iso],
    ['Software', e.software],
    ['Archivo modificado', m.modificado && fechaLarga(m.modificado)],
  ].filter(([, v]) => v);
}

