/* Genera un patrón SVG en malla (filas alternadas) para repetirlo en diagonal */
function crearPatron(wm) {
  const tam = wm.tamano;
  const claro = wm.color === 'claro';
  const fill = claro ? '#ffffff' : '#000000';
  const stroke = claro ? 'rgba(0,0,0,0.45)' : 'rgba(255,255,255,0.45)';
  const usaLogo = wm.modo === 'logo' && wm.logo;
  const texto = (wm.texto || ' ').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const cw = usaLogo ? tam * 5 : Math.max(40, (wm.texto || '').length * tam * 0.64);
  const ch = usaLogo ? tam * 2.4 : tam * 1.3;
  const w = Math.round(cw + wm.espacio * 2);
  const h = Math.round(ch + wm.espacio);

  const item = (cx, cy) =>
    usaLogo
      ? `<image href="${wm.logo}" x="${cx - cw / 2}" y="${cy - ch / 2}" width="${cw}" height="${ch}" preserveAspectRatio="xMidYMid meet"/>`
      : `<text x="${cx}" y="${cy + tam * 0.35}" text-anchor="middle" font-family="Arial,Helvetica,sans-serif" font-weight="700" font-size="${tam}" fill="${fill}" stroke="${stroke}" stroke-width="0.8" paint-order="stroke">${texto}</text>`;

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h * 2}" viewBox="0 0 ${w} ${h * 2}">${item(w / 2, h / 2)}${item(0, h * 1.5)}${item(w, h * 1.5)}</svg>`;
  return { url: `url("data:image/svg+xml,${encodeURIComponent(svg)}")`, w, h: h * 2 };
}

function reducirLogo(file, max = 400) {
  return new Promise((resolve) => {
    const lector = new FileReader();
    lector.onload = () => {
      const img = new Image();
      img.onload = () => {
        const k = Math.min(1, max / Math.max(img.width, img.height));
        const c = document.createElement('canvas');
        c.width = Math.round(img.width * k);
        c.height = Math.round(img.height * k);
        c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
        resolve(c.toDataURL('image/png'));
      };
      img.src = lector.result;
    };
    lector.readAsDataURL(file);
  });
}

/* ============================================================
   SOPORTE RAW + DETECCIÓN DE ORIENTACIÓN
   Los navegadores no pueden mostrar un RAW, pero casi todos traen
   dentro una vista previa JPG grande. La extraemos, corregimos la
   rotación y la reducimos a un JPG ligero (máx. 2400px).
   ============================================================ */
const EXT_RAW = /\.(cr2|cr3|crw|nef|nrw|arw|srf|sr2|dng|orf|rw2|raf|pef|srw|3fr|erf|kdc|mrw|raw|rwl|iiq)$/i;
const ACEPTA = 'image/*,.cr2,.cr3,.crw,.nef,.nrw,.arw,.srf,.sr2,.dng,.orf,.rw2,.raf,.pef,.srw,.3fr,.erf,.kdc,.mrw,.raw,.rwl,.iiq';

const formaDe = (w, h) => (w > h * 1.05 ? 'horizontal' : h > w * 1.05 ? 'vertical' : 'cuadrada');
const ETIQUETA_FORMA = { horizontal: 'Horizontal', vertical: 'Vertical', cuadrada: 'Cuadrada' };

/* Lee la etiqueta de orientación EXIF (0x0112) de un bloque TIFF. Devuelve 0 si no la encuentra */
function leerOrientacion(v, tiff) {
  try {
    const little = v.getUint16(tiff) === 0x4949;
    const magic = v.getUint16(tiff + 2, little);
    if (magic !== 42 && magic !== 0x55 && magic !== 0x4f52) return 0;
    const ifd = tiff + v.getUint32(tiff + 4, little);
    const n = v.getUint16(ifd, little);
    for (let i = 0; i < n; i++) {
      const e = ifd + 2 + i * 12;
      if (v.getUint16(e, little) === 0x0112) {
        const o = v.getUint16(e + 8, little);
        return o >= 1 && o <= 8 ? o : 0;
      }
    }
  } catch (err) { /* fuera de rango: sin orientación */ }
  return 0;
}

function orientacionContenedor(v, n) {
  if (n < 16) return 0;
  const cab = v.getUint16(0);
  if (cab === 0x4949 || cab === 0x4d4d) {
    const o = leerOrientacion(v, 0);
    if (o) return o;
  }
  // CR3 y similares: buscar el bloque TIFF dentro de los primeros 256 KB
  const lim = Math.min(n - 8, 262144);
  for (let i = 0; i < lim; i++) {
    const w = v.getUint32(i);
    if (w === 0x49492a00 || w === 0x4d4d002a) {
      const o = leerOrientacion(v, i);
      if (o) return o;
    }
  }
  return 0;
}

function orientacionJpeg(u8, v, ini, fin) {
  let p = ini + 2;
  while (p + 4 < fin && u8[p] === 0xff) {
    const m = u8[p + 1];
    if (m === 0xda || m === 0xd9) break;
    const len = (u8[p + 2] << 8) | u8[p + 3];
    if (m === 0xe1 && u8[p + 4] === 0x45 && u8[p + 5] === 0x78) return leerOrientacion(v, p + 10);
    p += 2 + len;
  }
  return 0;
}

/* Recorre la estructura de un JPEG desde su inicio y devuelve dónde termina (o -1) */
function finJpeg(u8, ini) {
  const n = u8.length;
  let p = ini + 2;
  while (p + 4 <= n) {
    if (u8[p] !== 0xff) return -1;
    const m = u8[p + 1];
    if (m === 0xff) { p++; continue; }
    if (m === 0xd9) return p + 2;
    if (m === 0x01 || (m >= 0xd0 && m <= 0xd7)) { p += 2; continue; }
    const len = (u8[p + 2] << 8) | u8[p + 3];
    if (len < 2) return -1;
    p += 2 + len;
    if (m === 0xda) {
      while (p + 1 < n) {
        if (u8[p] === 0xff) {
          const q = u8[p + 1];
          if (q === 0xd9) return p + 2;
          if (q === 0x00 || (q >= 0xd0 && q <= 0xd7)) { p += 2; continue; }
          if (q === 0xff) { p++; continue; }
          break; // otro marcador (JPEG progresivo)
        }
        p++;
      }
    }
  }
  return -1;
}

/* Busca todos los JPG incrustados y los devuelve del más grande al más pequeño */
function extraerPreviews(u8) {
  const res = [];
  const n = u8.length;
  for (let i = 0; i < n - 3; i++) {
    if (u8[i] === 0xff && u8[i + 1] === 0xd8 && u8[i + 2] === 0xff) {
      const fin = finJpeg(u8, i);
      if (fin > i) { res.push([i, fin]); i = fin - 1; }
    }
  }
  return res.sort((a, b) => (b[1] - b[0]) - (a[1] - a[0]));
}

/* Dibuja el bitmap aplicando la orientación EXIF y lo reduce a un JPG */
function bitmapAJpeg(bmp, o, max = 2400) {
  const gira = o >= 5;
  const W = gira ? bmp.height : bmp.width;
  const H = gira ? bmp.width : bmp.height;
  const k = Math.min(1, max / Math.max(W, H));
  const c = document.createElement('canvas');
  c.width = Math.round(W * k);
  c.height = Math.round(H * k);
  const x = c.getContext('2d');
  x.scale(k, k);
  switch (o) {
    case 2: x.transform(-1, 0, 0, 1, W, 0); break;
    case 3: x.transform(-1, 0, 0, -1, W, H); break;
    case 4: x.transform(1, 0, 0, -1, 0, H); break;
    case 5: x.transform(0, 1, 1, 0, 0, 0); break;
    case 6: x.transform(0, 1, -1, 0, W, 0); break;
    case 7: x.transform(0, -1, -1, 0, W, H); break;
    case 8: x.transform(0, -1, 1, 0, 0, H); break;
    default: break;
  }
  x.drawImage(bmp, 0, 0);
  return new Promise((resolve) => c.toBlob((b) => resolve({ blob: b, ancho: c.width, alto: c.height }), 'image/jpeg', 0.9));
}

const medirImagen = (url) =>
  new Promise((resolve) => {
    const img = new Image();
    img.onload = () => resolve({ ancho: img.naturalWidth, alto: img.naturalHeight });
    img.onerror = () => resolve(null);
    img.src = url;
  });

/* Convierte cualquier archivo subido en { url, ancho, alto, forma, raw } o null si no se puede mostrar */
async function procesarImagen(file) {
  const normal = /^image\/(jpeg|png|webp|gif|avif)$/i.test(file.type);
  if (normal) {
    const url = URL.createObjectURL(file);
    const dim = await medirImagen(url);
    if (!dim) return null;
    const cab = new Uint8Array(await file.slice(0, 262144).arrayBuffer());
    return { url, ...dim, forma: formaDe(dim.ancho, dim.alto), raw: false, nombre: file.name, meta: datosMeta(file, cab) };
  }

  if (!EXT_RAW.test(file.name) && !file.type.startsWith('image/')) return null;

  const buf = await file.arrayBuffer();
  const u8 = new Uint8Array(buf);
  const v = new DataView(buf);
  const candidatos = extraerPreviews(u8);
  const oRaw = orientacionContenedor(v, u8.length);

  for (const [a, b] of candidatos.slice(0, 5)) {
    const blob = new Blob([u8.subarray(a, b)], { type: 'image/jpeg' });
    let bmp;
    try {
      try { bmp = await createImageBitmap(blob, { imageOrientation: 'none' }); }
      catch (err) { bmp = await createImageBitmap(blob); }
    } catch (err) { continue; }

    const oJpg = orientacionJpeg(u8, v, a, b);
    const o = oRaw > 1 ? oRaw : (oJpg || oRaw || 1);
    const { blob: salida, ancho, alto } = await bitmapAJpeg(bmp, o);
    if (bmp.close) bmp.close();
    if (!salida) continue;
    return { url: URL.createObjectURL(salida), ancho, alto, forma: formaDe(ancho, alto), raw: true, nombre: file.name, meta: datosMeta(file, u8) };
  }
  return null;
}

/* ============================================================
   COMPONENTES BASE
   ============================================================ */
function Marca({ wm, escala = 1 }) {
  const patron = useMemo(() => crearPatron(wm), [wm.modo, wm.texto, wm.logo, wm.tamano, wm.espacio, wm.color]);
  return (
    <div
      className="wm-layer"
      style={{
        backgroundImage: patron.url,
        backgroundSize: `${patron.w * escala}px ${patron.h * escala}px`,
        opacity: wm.opacidad,
        transform: `translate(-50%, -50%) rotate(${wm.angulo}deg)`,
      }}
    />
  );
}

function Modal({ titulo, children, onClose }) {
  return (
    <div className="modal-bg" onClick={onClose}>
      <div className="modal" onClick={(e) => e.stopPropagation()}>
        <h3>{titulo}</h3>
        {children}
      </div>
    </div>
  );
}

const Segmentado = ({ valor, opciones, onChange }) => (
  <div className="seg">
    {opciones.map(([v, etiqueta]) => (
      <button key={v} type="button" className={valor === v ? 'on' : ''} onClick={() => onChange(v)}>{etiqueta}</button>
    ))}
  </div>
);

/* ============================================================
   VISOR DE FOTOS (cliente y fotógrafo): zoom, arrastre, pellizco,
   flechas del teclado, nombre de archivo y panel de metadatos
   ============================================================ */
function Visor({ fotos, indice, onCambiar, onCerrar, wm, admin, cliente, onLike, onNota }) {
  const f = fotos[indice];
  const [z, setZ] = useState(1);
  const [p, setP] = useState({ x: 0, y: 0 });
  const [panel, setPanel] = useState(!!admin);
  const [mueve, setMueve] = useState(false);
  const [nota, setNota] = useState(false);
  const [texto, setTexto] = useState('');
  const ptr = useRef(new Map());
  const caja = useRef(null);
  const n = fotos.length;

  const zoom = (v) => {
    const k = Math.min(6, Math.max(1, v));
    setZ(k);
    if (k === 1) setP({ x: 0, y: 0 });
  };
  const ir = (d) => { setNota(false); setZ(1); setP({ x: 0, y: 0 }); onCambiar((indice + d + n) % n); };

  useEffect(() => {
    const tecla = (e) => {
      if (/^(TEXTAREA|INPUT)$/.test(e.target.tagName)) return;
      if (e.key === 'Escape') onCerrar();
      else if (e.key === 'ArrowRight') ir(1);
      else if (e.key === 'ArrowLeft') ir(-1);
      else if (e.key === '+' || e.key === '=') zoom(z + 0.5);
      else if (e.key === '-') zoom(z - 0.5);
      else if (e.key === '0') zoom(1);
    };
    window.addEventListener('keydown', tecla);
    return () => window.removeEventListener('keydown', tecla);
  });

  useEffect(() => {
    const el = caja.current;
    const rueda = (e) => { e.preventDefault(); zoom(z * (e.deltaY < 0 ? 1.15 : 0.87)); };
    el.addEventListener('wheel', rueda, { passive: false });
    return () => el.removeEventListener('wheel', rueda);
  });

  const abajo = (e) => {
    e.currentTarget.setPointerCapture(e.pointerId);
    ptr.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    setMueve(true);
  };
  const mover = (e) => {
    const m = ptr.current;
    const a = m.get(e.pointerId);
    if (!a) return;
    if (m.size === 2) {
      const otro = [...m.entries()].find(([id]) => id !== e.pointerId)[1];
      const antes = Math.hypot(a.x - otro.x, a.y - otro.y);
      const ahora = Math.hypot(e.clientX - otro.x, e.clientY - otro.y);
      if (antes) zoom(z * (ahora / antes));
    } else if (z > 1) {
      setP((o) => ({ x: o.x + e.clientX - a.x, y: o.y + e.clientY - a.y }));
    }
    m.set(e.pointerId, { x: e.clientX, y: e.clientY });
  };
  const arriba = (e) => { ptr.current.delete(e.pointerId); if (!ptr.current.size) setMueve(false); };

  if (!f) return null;
  const liked = cliente && f.likes.some((l) => l.email === cliente.email);
  const mias = cliente ? f.notas.filter((nt) => nt.email === cliente.email) : [];
  const enviar = () => { if (!texto.trim()) return; onNota(f.id, texto.trim()); setTexto(''); };
  const sinExif = !f.meta || !f.meta.exif || !Object.keys(f.meta.exif).length;

  return (
    <div className="visor" onContextMenu={(e) => !admin && e.preventDefault()}>
      <div className="vz-bar">
        <div className="vz-name">
          <b title={nombreDe(f, indice)}>{nombreDe(f, indice)}</b>
          <span>{indice + 1} / {n}</span>
        </div>
        <div className="vz-tools">
          <button className="vz-btn" onClick={() => zoom(z - 0.5)} aria-label="Alejar"><Icon name="zoomOut" /></button>
          <button className="vz-btn txt" onClick={() => zoom(1)} title="Restablecer">{Math.round(z * 100)}%</button>
          <button className="vz-btn" onClick={() => zoom(z + 0.5)} aria-label="Acercar"><Icon name="zoomIn" /></button>
          {admin && <button className={`vz-btn ${panel ? 'on' : ''}`} onClick={() => setPanel((s) => !s)} aria-label="Información"><Icon name="info" /></button>}
          <button className="vz-btn" onClick={onCerrar} aria-label="Cerrar"><Icon name="x" /></button>
        </div>
      </div>

      <div className="vz-body">
        <div className="vz-main">
          <div
            className="vz-stage"
            ref={caja}
            style={{ cursor: z > 1 ? (mueve ? 'grabbing' : 'grab') : 'zoom-in' }}
            onPointerDown={abajo}
            onPointerMove={mover}
            onPointerUp={arriba}
            onPointerCancel={arriba}
            onDoubleClick={() => zoom(z > 1 ? 1 : 2.5)}
          >
            <img
              src={f.url}
              alt={nombreDe(f, indice)}
              draggable={false}
              style={{ transform: `translate(${p.x}px, ${p.y}px) scale(${z})`, transition: mueve ? 'none' : 'transform .15s' }}
            />
            {!admin && wm && <Marca wm={wm} />}
          </div>
          {n > 1 && <button className="vz-nav l" onClick={() => ir(-1)} aria-label="Anterior"><Icon name="left" size={22} /></button>}
          {n > 1 && <button className="vz-nav r" onClick={() => ir(1)} aria-label="Siguiente"><Icon name="right" size={22} /></button>}
        </div>

        {admin && panel && (
          <aside className="vz-side">
            <h4>Información de la foto</h4>
            <dl>
              {filasMeta(f, indice).map(([k, v]) => (
                <div key={k}><dt>{k}</dt><dd>{v}</dd></div>
              ))}
            </dl>
            {sinExif && <p className="vz-hint">Esta foto no trae datos EXIF (cámara, lente, ISO…). Las fotos subidas desde la cámara o en RAW sí los incluyen.</p>}
            <h4>Actividad del cliente</h4>
            {f.likes.length === 0 && f.notas.length === 0 && <p className="vz-hint">Sin actividad todavía.</p>}
            {f.likes.map((l) => <p className="vz-act" key={l.id}><Icon name="heart" size={13} fill /> {l.nombre} <small>{l.email}</small></p>)}
            {f.notas.map((nt) => <p className="vz-act nota" key={nt.id}><Icon name="message" size={13} /> <b>{nt.nombre}:</b> {nt.texto}</p>)}
          </aside>
        )}
      </div>

      {!admin && cliente && (
        <div className="vz-foot">
          {nota && (
            <div className="vz-note">
              {mias.map((nt) => <p className="my-note" key={nt.id}>{nt.texto}</p>)}
              <textarea rows="2" placeholder="Escribe un comentario o sugerencia para esta foto…" value={texto} onChange={(e) => setTexto(e.target.value)} />
              <button className="btn primary" onClick={enviar}>Enviar</button>
            </div>
          )}
          <span />
          <button className={`vz-heart ${liked ? 'liked' : ''}`} onClick={() => onLike(f.id)} aria-label="Me gusta"><Icon name="heart" size={22} fill={liked} /><span>{f.likes.length}</span></button>
          <button className={`vz-cmt ${nota ? 'on' : ''}`} onClick={() => setNota((s) => !s)}><Icon name="message" size={18} /> Comentar{mias.length ? ` (${mias.length})` : ''}</button>
        </div>
      )}
    </div>
  );
}

/* ============================================================
   VISTAS DEL PANEL DEL FOTÓGRAFO
   ============================================================ */
function VistaColecciones({ colecciones, abierta, onVer, onPublicar, onCompartir, onAbrir, onCerrar, onNueva, onBorrar, onSubir, onBorrarFoto, onPortada, procesando, aviso, onCerrarAviso }) {
  const totalFotos = colecciones.reduce((s, c) => s + c.fotos.length, 0);
  const totalLikes = colecciones.reduce((s, c) => s + c.fotos.reduce((a, f) => a + f.likes.length, 0), 0);
  const totalNotas = colecciones.reduce((s, c) => s + c.fotos.reduce((a, f) => a + f.notas.length, 0), 0);

  if (abierta) {
    const subir = (files) => onSubir(abierta.id, files);
    return (
      <div className="page">
        <div className="page-head">
          <div>
            <button className="btn" onClick={onCerrar} style={{ marginBottom: 14 }}><Icon name="back" size={16} /> Colecciones</button>
            <h1 className="title">{abierta.nombre}</h1>
            <p className="sub">{abierta.fecha} · {abierta.fotos.length} fotos</p>
          </div>
          <label className="btn primary" style={{ cursor: 'pointer' }}>
            <Icon name="upload" size={16} /> Subir fotos
            <input type="file" multiple accept={ACEPTA} hidden onChange={(e) => { subir(e.target.files); e.target.value = ''; }} />
          </label>
        </div>

        {procesando && (
          <div className="banner"><span className="spin" /> Procesando foto {Math.min(procesando.hecho + 1, procesando.total)} de {procesando.total}… los RAW tardan unos segundos cada uno.</div>
        )}
        {aviso && (
          <div className="banner warn">{aviso} <button className="link" onClick={onCerrarAviso}>Cerrar</button></div>
        )}

        {abierta.fotos.length === 0 ? (
          <div
            className="dropzone"
            onDragOver={(e) => e.preventDefault()}
            onDrop={(e) => { e.preventDefault(); subir(e.dataTransfer.files); }}
          >
            <Icon name="image" size={32} />
            <p>Arrastra tus fotos aquí o usa el botón “Subir fotos”. Acepta JPG, PNG, WebP y RAW (CR2, CR3, NEF, ARW, DNG y más).</p>
          </div>
        ) : (
          <div
            className="photos"
            onDragOver={(e) => e.preventDefault()}
            onDrop={(e) => { e.preventDefault(); subir(e.dataTransfer.files); }}
          >
            {abierta.fotos.map((f, i) => (
              <div className="ph" key={f.id} onClick={() => onVer(abierta.id, f.id)} title="Abrir foto y ver información">
                <img src={f.url} alt={nombreDe(f, i)} />
                <span className="ph-name">{nombreDe(f, i)}</span>
                <div className="ph-actions">
                  <button className="mini" title="Usar como portada" onClick={(e) => { e.stopPropagation(); onPortada(abierta.id, f.id); }}>
                    <Icon name={(abierta.portadaId || abierta.fotos[0].id) === f.id ? 'check' : 'image'} size={14} />
                  </button>
                  <button className="mini" title="Eliminar foto" onClick={(e) => { e.stopPropagation(); onBorrarFoto(abierta.id, f.id); }}><Icon name="trash" size={14} /></button>
                </div>
                <div className="ph-meta">
                  <span><Icon name="heart" size={12} fill /> {f.likes.length}</span>
                  <span><Icon name="message" size={12} /> {f.notas.length}</span>
                  {f.forma && <span className="forma">{f.raw ? 'RAW · ' : ''}{ETIQUETA_FORMA[f.forma]}</span>}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="page">
      <div className="page-head">
        <div>
          <h1 className="title">Colecciones</h1>
          <p className="sub">Administra tus sesiones y galerías fotográficas.</p>
        </div>
        <button className="btn primary" onClick={onNueva}><Icon name="plus" size={16} /> Nueva colección</button>
      </div>

      <div className="stats">
        <div className="stat"><b>{colecciones.length}</b><span>Colecciones</span></div>
        <div className="stat"><b>{totalFotos}</b><span>Fotos</span></div>
        <div className="stat"><b>{totalLikes}</b><span>Me gusta</span></div>
        <div className="stat"><b>{totalNotas}</b><span>Sugerencias</span></div>
      </div>

      {colecciones.length === 0 ? (
        <div className="dropzone"><Icon name="folder" size={32} /><p>Aún no tienes colecciones. Crea la primera.</p></div>
      ) : (
        <div className="cards">
          {colecciones.map((c) => {
            const portada = portadaDe(c);
            return (
              <div className="card" key={c.id} onClick={() => onAbrir(c.id)}>
                <div className="card-cover">
                  {portada ? <img src={portada} alt={c.nombre} /> : <div className="empty-cover"><Icon name="image" size={28} /></div>}
                  <button className={`pub ${c.publica ? 'on' : ''}`} title={c.publica ? 'Visible para el cliente: clic para ocultar' : 'Oculta: clic para publicar'} onClick={(e) => { e.stopPropagation(); onPublicar(c.id); }}>
                    <i /> {c.publica ? 'Público' : 'Privado'}
                  </button>
                </div>
                <div className="card-body">
                  <div style={{ minWidth: 0 }}>
                    <h4>{c.nombre}</h4>
                    <span>{c.fecha} · {c.fotos.length} fotos</span>
                  </div>
                  <div className="card-acts"><button className="icon-btn" title="Compartir enlace" onClick={(e) => { e.stopPropagation(); onCompartir(c.id); }}><Icon name="external" size={16} /></button><button className="icon-btn danger" title="Eliminar colección" onClick={(e) => { e.stopPropagation(); onBorrar(c); }}>
                    <Icon name="trash" size={16} />
                  </button></div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function VistaNotificaciones({ items, noLeidas, onLeer, onIrACol, onVer }) {
  return (
    <div className="page">
      <div className="page-head">
        <div>
          <h1 className="title">Notificaciones <span className="live"><i /> En vivo</span></h1>
          <p className="sub">Selecciones y sugerencias que dejan tus clientes en cada foto.</p>
        </div>
        <button className="btn" disabled={noLeidas === 0} onClick={onLeer}><Icon name="check" size={16} /> Marcar como leídas</button>
      </div>

      <div className="panel" style={{ padding: '4px 22px' }}>
        {items.length === 0 ? (
          <div className="dropzone" style={{ border: 0 }}>
            <Icon name="bell" size={32} />
            <p>Ningún cliente ha interactuado todavía. Cuando den “Me gusta” o dejen una nota, aparecerá aquí.</p>
          </div>
        ) : (
          items.map((n) => (
            <div className="notif" key={`${n.tipo}-${n.id}`}>
              <img src={n.foto.url} alt="" title="Abrir foto" onClick={() => onVer(n.colId, n.foto.id)} />
              <div className="notif-body">
                <p>
                  <strong>{n.nombre}</strong> {n.tipo === 'like' ? 'marcó con me gusta' : 'dejó una sugerencia en'} la foto {n.num} de{' '}
                  <button className="link" onClick={() => onIrACol(n.colId)}>{n.col}</button>
                </p>
                <div className="file"><Icon name="image" size={13} /> <button className="link" title="Abrir foto" onClick={() => onVer(n.colId, n.foto.id)}>{nombreDe(n.foto, n.num - 1)}</button></div>
                {n.tipo === 'nota' && <blockquote>{n.texto}</blockquote>}
                <small>{n.email} · {fechaLarga(n.fecha)}</small>
              </div>
              <span className={`tipo ${n.tipo}`}><Icon name={n.tipo === 'like' ? 'heart' : 'message'} size={14} fill={n.tipo === 'like'} /></span>
              {n.fecha > n.vistoHasta && <span className="dot" title="Sin leer" />}
            </div>
          ))
        )}
      </div>
    </div>
  );
}

function VistaMarcaAgua({ wm, setWm, fotoDemo }) {
  const subirLogo = async (e) => {
    const f = e.target.files[0];
    if (!f) return;
    setWm('logo', await reducirLogo(f));
    setWm('modo', 'logo');
    e.target.value = '';
  };

  return (
    <div className="page">
      <div className="page-head">
        <div>
          <h1 className="title">Marca de agua</h1>
          <p className="sub">Se repite en malla diagonal sobre cada foto que ve el cliente.</p>
        </div>
      </div>

      <div className="split">
        <div className="panel">
          <div className="field">
            <label>Tipo de marca</label>
            <Segmentado valor={wm.modo} opciones={[['texto', 'Texto'], ['logo', 'Logo (PNG)']]} onChange={(v) => setWm('modo', v)} />
          </div>

          {wm.modo === 'texto' ? (
            <div className="field">
              <label>Texto</label>
              <input type="text" value={wm.texto} onChange={(e) => setWm('texto', e.target.value)} />
            </div>
          ) : (
            <div className="field">
              <label>Logo (PNG con fondo transparente)</label>
              <label className="btn" style={{ cursor: 'pointer' }}>
                <Icon name="upload" size={16} /> {wm.logo ? 'Cambiar logo' : 'Subir logo'}
                <input type="file" accept="image/png,image/svg+xml,image/webp" hidden onChange={subirLogo} />
              </label>
              {!wm.logo && <small className="hint">Sin logo se mostrará la previsualización vacía.</small>}
            </div>
          )}

          <div className="field">
            <label>Opacidad <b>{Math.round(wm.opacidad * 100)}%</b></label>
            <input type="range" min="0.1" max="0.9" step="0.05" value={wm.opacidad} onChange={(e) => setWm('opacidad', parseFloat(e.target.value))} />
          </div>
          <div className="field">
            <label>Tamaño <b>{wm.tamano}px</b></label>
            <input type="range" min="10" max="48" step="1" value={wm.tamano} onChange={(e) => setWm('tamano', parseInt(e.target.value, 10))} />
          </div>
          <div className="field">
            <label>Separación (cantidad en la imagen) <b>{wm.espacio}px</b></label>
            <input type="range" min="0" max="120" step="5" value={wm.espacio} onChange={(e) => setWm('espacio', parseInt(e.target.value, 10))} />
          </div>
          <div className="field">
            <label>Ángulo <b>{wm.angulo}°</b></label>
            <input type="range" min="-60" max="60" step="5" value={wm.angulo} onChange={(e) => setWm('angulo', parseInt(e.target.value, 10))} />
          </div>
          {wm.modo === 'texto' && (
          <div className="field" style={{ marginBottom: 0 }}>
            <label>Color</label>
            <Segmentado valor={wm.color} opciones={[['claro', 'Claro'], ['oscuro', 'Oscuro']]} onChange={(v) => setWm('color', v)} />
          </div>
          )}
        </div>

        <div className="panel">
          <label className="lbl">Previsualización en vivo</label>
          <div className="preview">
            <img src={fotoDemo} alt="Previsualización" />
            <Marca wm={wm} />
          </div>
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   DISEÑO DE LA GALERÍA + VISTA DEL CLIENTE (estilo Pixieset)
   ============================================================ */
const TEMAS = [['claro', 'Blanco'], ['marfil', 'Marfil'], ['gris', 'Gris'], ['oscuro', 'Oscuro'], ['negro', 'Negro']];
const MEDIDAS = {
  tamano: { pequena: '200px', media: '290px', grande: '420px' },
  espacio: { compacto: '6px', normal: '18px', amplio: '36px' },
  bordes: { cuadrado: '0px', suave: '10px', redondo: '24px' },
};
const DISENO_BASE = { titulo: 'Mi galería', subtitulo: 'Sesión fotográfica exclusiva', mensaje: 'Toca el corazón en tus favoritas y deja notas con tus sugerencias.', acento: '#b08d57', fuente: 'cormorant', portada: 'completa', tema: 'oscuro', estilo: 'mosaico', tamano: 'media', espacio: 'normal', bordes: 'suave', verNombre: true, verNumero: true };
const DEMO = { nombre: 'Cliente demo', email: 'demo@galeria.com' };
const SINO = [[true, 'Sí'], [false, 'No']];

function VistaDiseno({ diseno, setDiseno, onPreview, coleccion, wm, colecciones, activaId, onElegir }) {
  const [equipo, setEquipo] = useState('pc');
  const [pantalla, setPantalla] = useState('galeria');
  const S = (k, ops) => <Segmentado valor={diseno[k]} opciones={ops} onChange={(v) => setDiseno(k, v)} />;
  const C = (t, children) => <div className="field"><label>{t}</label>{children}</div>;

  return (
    <div className="page wide">
      <div className="page-head">
        <div>
          <h1 className="title">Diseño y estilos</h1>
          <p className="sub">Personaliza la galería y mira el resultado en vivo, como lo verá tu cliente.</p>
        </div>
        <button className="btn dark" onClick={onPreview}><Icon name="eye" size={16} /> Pantalla completa</button>
      </div>

      <div className="dsg">
        <div className="panel dsg-ctrl">
          <h4 className="grp">Colección a editar</h4>
          {colecciones.length === 0 ? <p className="sub">Primero crea una colección.</p> : (
            <div className="field">
              <select value={activaId} onChange={(e) => onElegir(Number(e.target.value))}>
                {colecciones.map((c) => <option key={c.id} value={c.id}>{c.nombre}</option>)}
              </select>
              <small className="hint">Cada colección guarda su propio diseño.</small>
            </div>
          )}
          <h4 className="grp">Textos</h4>
          {C('Título principal', <input type="text" value={diseno.titulo} onChange={(e) => setDiseno('titulo', e.target.value)} />)}
          {C('Subtítulo / referencia', <input type="text" value={diseno.subtitulo} onChange={(e) => setDiseno('subtitulo', e.target.value)} />)}
          {C('Mensaje de bienvenida', <input type="text" value={diseno.mensaje} onChange={(e) => setDiseno('mensaje', e.target.value)} />)}

          <h4 className="grp">Portada</h4>
          {C('Estilo de portada', S('portada', [['completa', 'Pantalla completa'], ['dividida', 'Dividida'], ['centrada', 'Centrada'], ['minima', 'Mínima']]))}

          <h4 className="grp">Estilo</h4>
          {C('Tipografía', S('fuente', [['moderna', 'Moderna'], ['elegante', 'Playfair'], ['cormorant', 'Cormorant'], ['montserrat', 'Montserrat'], ['mono', 'Mono']]))}
          {C('Fondo y tema', S('tema', TEMAS))}
          {C('Color de acento', (
            <div className="swatches">
              {COLORES.map((c) => (
                <button key={c} type="button" aria-label={c} className={diseno.acento === c ? 'on' : ''} style={{ background: c }} onClick={() => setDiseno('acento', c)} />
              ))}
              <input type="color" value={diseno.acento} onChange={(e) => setDiseno('acento', e.target.value)} aria-label="Color personalizado" title="Color personalizado" />
            </div>
          ))}

          <h4 className="grp">Fotos</h4>
          {C('Distribución', S('estilo', [['cuadricula', 'Cuadrícula'], ['mosaico', 'Mosaico'], ['columna', 'Una columna']]))}
          {C('Tamaño de las fotos', S('tamano', [['pequena', 'Pequeñas'], ['media', 'Medianas'], ['grande', 'Grandes']]))}
          {C('Espaciado', S('espacio', [['compacto', 'Compacto'], ['normal', 'Normal'], ['amplio', 'Amplio']]))}
          {C('Esquinas', S('bordes', [['cuadrado', 'Cuadradas'], ['suave', 'Suaves'], ['redondo', 'Redondas']]))}
          {C('Mostrar nombre del archivo', S('verNombre', SINO))}
          <div className="field" style={{ marginBottom: 0 }}>{C('Mostrar número de foto', S('verNumero', SINO))}</div>
        </div>

        <div className="panel dsg-view">
          <div className="dsg-bar">
            <Segmentado valor={pantalla} opciones={[['acceso', 'Acceso'], ['galeria', 'Galería']]} onChange={setPantalla} />
            <Segmentado valor={equipo} opciones={[['pc', 'Computador'], ['movil', 'Móvil']]} onChange={setEquipo} />
          </div>
          <div className={`frame ${equipo}`}>
            <VistaCliente
              embed
              coleccion={coleccion}
              diseno={diseno}
              wm={wm}
              cliente={pantalla === 'galeria' ? DEMO : null}
              onEntrar={() => setPantalla('galeria')}
              onSalir={() => setPantalla('acceso')}
              onLike={() => {}}
              onNota={() => {}}
            />
          </div>
          <small className="hint">En la vista previa puedes abrir las fotos, acercarlas y navegar igual que tu cliente. Los “me gusta” no se guardan aquí.</small>
        </div>
      </div>
    </div>
  );
}

function Foto({ foto, num, wm, cliente, g, onAbrir, onLike, onNota }) {
  const [abierta, setAbierta] = useState(false);
  const [dim, setDim] = useState(foto.ancho ? { w: foto.ancho, h: foto.alto } : null);
  const forma = dim ? formaDe(dim.w, dim.h) : 'horizontal';
  const [texto, setTexto] = useState('');
  const mias = foto.notas.filter((n) => n.email === cliente.email);
  const liked = foto.likes.some((l) => l.email === cliente.email);
  const etiqueta = [g.verNumero && `Foto ${num}`, g.verNombre && nombreDe(foto, num - 1)].filter(Boolean).join(' · ');

  const enviar = () => {
    if (!texto.trim()) return;
    onNota(texto.trim());
    setTexto('');
  };

  return (
    <div className="shot">
      <div
        className={`shot-img f-${forma}`}
        style={dim && g.estilo !== 'cuadricula' ? { aspectRatio: `${dim.w} / ${dim.h}` } : undefined}
        onClick={onAbrir}
        title="Abrir foto"
      >
        <img
          src={foto.url}
          alt={nombreDe(foto, num - 1)}
          draggable={false}
          onLoad={(e) => { if (!dim) setDim({ w: e.target.naturalWidth, h: e.target.naturalHeight }); }}
        />
        <Marca wm={wm} escala={0.75} />
        <div className="shield" />
      </div>
      <div className="shot-bar">
        <span className="shot-num" title={etiqueta}>{etiqueta}</span>
        <div>
          <button className={`act ${liked ? 'liked' : ''}`} onClick={onLike} aria-label="Me gusta">
            <Icon name="heart" fill={liked} /> {foto.likes.length}
          </button>
          <button className="act" onClick={() => setAbierta((a) => !a)} aria-label="Dejar nota">
            <Icon name="message" /> {mias.length || ''}
          </button>
        </div>
      </div>
      {abierta && (
        <div className="note-box">
          {mias.map((n) => <p className="my-note" key={n.id}>{n.texto}</p>)}
          <textarea rows="2" placeholder="Escribe una sugerencia para esta foto…" value={texto} onChange={(e) => setTexto(e.target.value)} />
          <button className="btn primary" style={{ marginTop: 8 }} onClick={enviar}>Enviar nota</button>
        </div>
      )}
    </div>
  );
}

function VistaCliente({ coleccion, diseno: g, wm, cliente, onEntrar, onSalir, onLike, onNota, onVolver, embed }) {
  const tema = g.tema;
  const [nombre, setNombre] = useState('');
  const [correo, setCorreo] = useState('');
  const [error, setError] = useState('');
  const [ver, setVer] = useState(null);
  const galRef = useRef(null);

  // Bloqueo de atajos de guardado/impresión
  useEffect(() => {
    const bloquear = (e) => {
      if ((e.ctrlKey || e.metaKey) && ['s', 'p', 'u'].includes(e.key.toLowerCase())) e.preventDefault();
    };
    window.addEventListener('keydown', bloquear);
    return () => window.removeEventListener('keydown', bloquear);
  }, []);

  const entrar = (e) => {
    e.preventDefault();
    if (!nombre.trim()) return setError('Escribe tu nombre completo.');
    if (!EMAIL_RE.test(correo.trim())) return setError('Escribe un correo electrónico válido.');
    setError('');
    onEntrar({ nombre: nombre.trim(), email: correo.trim().toLowerCase() });
  };

  const fotos = coleccion ? coleccion.fotos : [];
  const portada = coleccion ? portadaDe(coleccion) : null;
  const fuente = { fontFamily: FUENTES[g.fuente] };
  const vars = { ...fuente, '--col': MEDIDAS.tamano[g.tamano], '--gap': MEDIDAS.espacio[g.espacio], '--rad': MEDIDAS.bordes[g.bordes] };
  const saludo = cliente && <small>Hola, {cliente.nombre}. {g.mensaje}</small>;
  const imgPortada = portada && (<><img src={portada} alt="" draggable={false} /><Marca wm={wm} escala={0.75} /><div className="shield" /></>);

  return (
    <div
      className={`cwrap t-${tema}`}
      style={vars}
      onContextMenu={(e) => e.preventDefault()}
      onDragStart={(e) => e.preventDefault()}
    >
      <div className="client">
        {onVolver && (
          <div className="preview-banner">
            <span>Vista previa del cliente{coleccion ? ` · ${coleccion.nombre}` : ''}</span>
            <button onClick={onVolver}><Icon name="back" size={14} /> Volver al panel</button>
          </div>
        )}

        <div className="c-top">
          <span className="c-brand"><Icon name="camera" size={18} /> {wm.texto || 'Galería'}</span>
          <div>
            {cliente && <button className="icon-btn" onClick={onSalir} aria-label="Salir" title="Salir"><Icon name="logout" size={16} /></button>}
          </div>
        </div>

        {!cliente ? (
          <form className="gate" onSubmit={entrar}>
            <div className="c-logo"><Logo alto={64} /></div>
            <h2 style={fuente}>{g.titulo}</h2>
            <p>{g.subtitulo}</p>
            <input type="text" placeholder="Tu nombre completo" value={nombre} onChange={(e) => setNombre(e.target.value)} />
            <input type="email" placeholder="Tu correo electrónico" value={correo} onChange={(e) => setCorreo(e.target.value)} />
            {error && <small className="err">{error}</small>}
            <button className="btn primary" type="submit" style={{ width: '100%', justifyContent: 'center' }}>Entrar a la galería</button>
          </form>
        ) : (
          <>
            {g.portada === 'completa' && (
              <header className="hero-full">
                {imgPortada}
                <div className="hero-txt">
                  <h1 style={fuente}>{g.titulo}</h1>
                  <p>{g.subtitulo}</p>
                  <button className="hero-btn" onClick={() => galRef.current && galRef.current.scrollIntoView({ behavior: 'smooth' })}>Ver galería</button>
                </div>
              </header>
            )}
            {g.portada === 'dividida' && (
              <header className="hero-split">
                <div>
                  <h1 style={fuente}>{g.titulo}</h1>
                  <p>{g.subtitulo}</p>
                  {saludo}
                </div>
                <div className="hs-img">{imgPortada}</div>
              </header>
            )}
            {(g.portada === 'centrada' || g.portada === 'minima') && (
              <div className={`c-hero ${g.portada === 'minima' ? 'min' : ''}`}>
                <h1 style={fuente}>{g.titulo}</h1>
                <p>{g.subtitulo}</p>
                {saludo}
              </div>
            )}

            <div ref={galRef} />
            {fotos.length === 0 ? (
              <div className="dropzone" style={{ margin: '0 auto', maxWidth: 420 }}><Icon name="image" size={32} /><p>Esta galería aún no tiene fotos.</p></div>
            ) : (
              <div className={`gallery ${g.estilo === 'cuadricula' ? 'grid' : g.estilo === 'mosaico' ? 'masonry' : 'single'}`}>
                {fotos.map((f, i) => (
                  <Foto key={f.id} foto={f} num={i + 1} wm={wm} cliente={cliente} g={g} onAbrir={() => setVer(i)} onLike={() => onLike(coleccion.id, f.id)} onNota={(t) => onNota(coleccion.id, f.id, t)} />
                ))}
              </div>
            )}
          </>
        )}
        {cliente && (
          <footer className="c-foot"><span>Galería creada con</span><Logo alto={34} /></footer>
        )}
      </div>

      {ver !== null && cliente && (
        <Visor fotos={fotos} indice={ver} onCambiar={setVer} onCerrar={() => setVer(null)} wm={wm} cliente={cliente} onLike={(id) => onLike(coleccion.id, id)} onNota={(id, tx) => onNota(coleccion.id, id, tx)} />
      )}
    </div>
  );
}

/* ============================================================
   APP
   ============================================================ */
const COL_INICIAL = [
  {
    id: 1,
    nombre: 'Boda Principal',
    fecha: '12 nov 2026',
    portadaId: null,
    publica: true,
    diseno: { ...DISENO_BASE, titulo: 'Boda María & Carlos' },
    fotos: [
      { id: 101, url: 'https://images.unsplash.com/photo-1519741497674-611481863552?w=1000', likes: [{ id: 1, nombre: 'María', email: 'maria@correo.com', fecha: Date.now() - 3600000 }], notas: [] },
      { id: 102, url: 'https://images.unsplash.com/photo-1511285560929-80b456fea0bc?w=1000', likes: [], notas: [] },
    ],
  },
];

export default function App() {
  const [vista, setVista] = useState('colecciones');
  const [preview, setPreview] = useState(false);

  const [colecciones, setColecciones] = useState(COL_INICIAL);
  const [abiertaId, setAbiertaId] = useState(null);
  const [activaId, setActivaId] = useState(COL_INICIAL[0].id);

  // Pega este bloque aquí:
  useEffect(() => {
    const hash = window.location.hash;
    if (hash.startsWith('#/g/')) {
      const colId = Number(hash.replace('#/g/', ''));
      if (colId) {
        const encontrada = colecciones.find((c) => c.id === colId);
        if (encontrada) {
          setActivaId(colId);
          setPreview(true);
        }
      }
    }
  }, [colecciones]);

  const [wm, setWmState] = useState({ modo: 'texto', texto: 'YOPOTO FOTOGRAFÍA', logo: null, opacidad: 0.35, tamano: 18, espacio: 30, angulo: -30, color: 'claro' });
  const setWm = (k, v) => setWmState((p) => ({ ...p, [k]: v }));


  const [adminOscuro, setAdminOscuro] = useState(() => { try { return localStorage.getItem('adm-oscuro') === '1'; } catch (err) { return false; } });
  useEffect(() => { try { localStorage.setItem('adm-oscuro', adminOscuro ? '1' : '0'); } catch (err) { /* sin acceso */ } }, [adminOscuro]);
  const [visorAdmin, setVisorAdmin] = useState(null);
  const [compartir, setCompartir] = useState(null);
  const [copiado, setCopiado] = useState(false);
  const [vistoHasta, setVistoHasta] = useState(0);
  const [cliente, setCliente] = useState(null);

  const [modalNueva, setModalNueva] = useState(false);
  const [nombreNueva, setNombreNueva] = useState('');
  const [aBorrar, setABorrar] = useState(null);
  const [procesando, setProcesando] = useState(null);
  const [aviso, setAviso] = useState('');

  const coleccionAbierta = colecciones.find((c) => c.id === abiertaId) || null;
  const coleccionActiva = colecciones.find((c) => c.id === activaId) || colecciones[0] || null;
  const diseno = (coleccionActiva && coleccionActiva.diseno) || DISENO_BASE;
  const setDiseno = (k, v) => coleccionActiva && mapCol(coleccionActiva.id, (c) => ({ ...c, diseno: { ...c.diseno, [k]: v } }));
  const fotoDemo = (coleccionActiva && portadaDe(coleccionActiva)) || 'https://images.unsplash.com/photo-1519741497674-611481863552?w=1000';

  /* Notificaciones derivadas del estado: se actualizan al instante */
  const notificaciones = useMemo(() => {
    const lista = [];
    colecciones.forEach((c) =>
      c.fotos.forEach((f, i) => {
        const base = { col: c.nombre, colId: c.id, foto: f, num: i + 1, vistoHasta };
        f.likes.forEach((l) => lista.push({ ...base, ...l, tipo: 'like' }));
        f.notas.forEach((n) => lista.push({ ...base, ...n, tipo: 'nota' }));
      })
    );
    return lista.sort((a, b) => b.fecha - a.fecha);
  }, [colecciones, vistoHasta]);
  const noLeidas = notificaciones.filter((n) => n.fecha > vistoHasta).length;

  /* ---------- acciones ---------- */
  const mapCol = (id, fn) => setColecciones((cs) => cs.map((c) => (c.id === id ? fn(c) : c)));
  const mapFoto = (colId, fotoId, fn) => mapCol(colId, (c) => ({ ...c, fotos: c.fotos.map((f) => (f.id === fotoId ? fn(f) : f)) }));

  const crearColeccion = () => {
    const nombre = nombreNueva.trim();
    if (!nombre) return;
    const nueva = { id: nuevoId(), nombre, fecha: hoy(), portadaId: null, publica: false, diseno: { ...DISENO_BASE, titulo: nombre }, fotos: [] };
    setColecciones((cs) => [...cs, nueva]);
    setNombreNueva('');
    setModalNueva(false);
    setAbiertaId(nueva.id);
    setActivaId(nueva.id);
  };

  const borrarColeccion = (id) => {
    setColecciones((cs) => cs.filter((c) => c.id !== id));
    if (abiertaId === id) setAbiertaId(null);
    setABorrar(null);
  };

  const subirFotos = async (colId, files) => {
    const lista = Array.from(files || []);
    if (!lista.length) return;
    const fallidas = [];
    setAviso('');
    setProcesando({ hecho: 0, total: lista.length });
    for (let i = 0; i < lista.length; i++) {
      let r = null;
      try { r = await procesarImagen(lista[i]); } catch (err) { r = null; }
      if (r) {
        mapCol(colId, (c) => ({ ...c, fotos: [...c.fotos, { id: nuevoId(), ...r, likes: [], notas: [] }] }));
      } else {
        fallidas.push(lista[i].name);
      }
      setProcesando({ hecho: i + 1, total: lista.length });
    }
    setProcesando(null);
    if (fallidas.length) setAviso(`No se pudo leer: ${fallidas.join(', ')}. Si es un RAW muy nuevo, expórtalo a JPG.`);
  };

  const borrarFoto = (colId, fotoId) =>
    mapCol(colId, (c) => ({ ...c, fotos: c.fotos.filter((f) => f.id !== fotoId), portadaId: c.portadaId === fotoId ? null : c.portadaId }));

  const publicar = (id) => mapCol(id, (c) => ({ ...c, publica: !c.publica }));

  const ponerPortada = (colId, fotoId) => mapCol(colId, (c) => ({ ...c, portadaId: fotoId }));

  const toggleLike = (colId, fotoId) =>
    mapFoto(colId, fotoId, (f) => {
      const ya = f.likes.some((l) => l.email === cliente.email);
      return { ...f, likes: ya ? f.likes.filter((l) => l.email !== cliente.email) : [...f.likes, { id: nuevoId(), nombre: cliente.nombre, email: cliente.email, fecha: Date.now() }] };
    });

  const agregarNota = (colId, fotoId, texto) =>
    mapFoto(colId, fotoId, (f) => ({ ...f, notas: [...f.notas, { id: nuevoId(), nombre: cliente.nombre, email: cliente.email, texto, fecha: Date.now() }] }));

  const salirPreview = () => { setPreview(false); setCliente(null); };

  const NAV = [
    ['colecciones', 'folder', 'Colecciones'],
    ['notificaciones', 'bell', 'Avisos'],
    ['marca', 'drop', 'Marca de agua'],
    ['diseno', 'palette', 'Diseño'],
  ];

  return (
    <div className={`app ${adminOscuro ? 'adm-dark' : ''}`} style={{ '--accent': diseno.acento }}>
      <style>{CSS}</style>

      {preview ? (
        <VistaCliente
          coleccion={coleccionActiva}
          diseno={diseno}
          wm={wm}
          cliente={cliente}
          onEntrar={setCliente}
          onSalir={() => setCliente(null)}
          onLike={toggleLike}
          onNota={agregarNota}
          onVolver={salirPreview}
        />
      ) : (
        <>
          <aside className="sidebar">
            <div className="brand"><Logo alto={84} /></div>
            <nav className="nav">
              {NAV.map(([id, icono, etiqueta]) => (
                <button key={id} className={`nav-btn ${vista === id ? 'on' : ''}`} onClick={() => { setVista(id); if (id !== 'colecciones') setAbiertaId(null); }}>
                  <Icon name={icono} />
                  <span>{etiqueta}</span>
                  {id === 'notificaciones' && noLeidas > 0 && <span className="badge">{noLeidas}</span>}
                </button>
              ))}
              <button className="nav-btn view-client" onClick={() => setPreview(true)}>
                <Icon name="external" />
                <span>Ver como cliente</span>
              </button>
              <button className="nav-btn theme-toggle" onClick={() => setAdminOscuro((o) => !o)}>
                <Icon name={adminOscuro ? 'sun' : 'moon'} />
                <span>{adminOscuro ? 'Modo claro' : 'Modo oscuro'}</span>
              </button>
            </nav>
            <div className="side-foot">Fotógrafo: Yoel Ramirez</div>
          </aside>

          <main className="main">
            <div className="m-brand"><Logo alto={46} /></div>
            {vista === 'colecciones' && (
              <VistaColecciones
                colecciones={colecciones}
                abierta={coleccionAbierta}
                onVer={(colId, fotoId) => setVisorAdmin({ colId, fotoId })}
                onPublicar={publicar}
                onCompartir={(id) => { setCopiado(false); setCompartir(id); }}
                onAbrir={(id) => { setAbiertaId(id); setActivaId(id); }}
                onCerrar={() => setAbiertaId(null)}
                onNueva={() => setModalNueva(true)}
                onBorrar={setABorrar}
                onSubir={subirFotos}
                procesando={procesando}
                aviso={aviso}
                onCerrarAviso={() => setAviso('')}
                onBorrarFoto={borrarFoto}
                onPortada={ponerPortada}
              />
            )}
            {vista === 'notificaciones' && (
              <VistaNotificaciones
                items={notificaciones}
                noLeidas={noLeidas}
                onVer={(colId, fotoId) => setVisorAdmin({ colId, fotoId })}
                onLeer={() => setVistoHasta(Date.now())}
                onIrACol={(id) => { setVista('colecciones'); setAbiertaId(id); setActivaId(id); }}
              />
            )}
            {vista === 'marca' && <VistaMarcaAgua wm={wm} setWm={setWm} fotoDemo={fotoDemo} />}
            {vista === 'diseno' && <VistaDiseno diseno={diseno} setDiseno={setDiseno} onPreview={() => setPreview(true)} coleccion={coleccionActiva} wm={wm} colecciones={colecciones} activaId={activaId} onElegir={setActivaId} />}
          </main>
        </>
      )}

      {!preview && visorAdmin && (() => {
        const col = colecciones.find((c) => c.id === visorAdmin.colId);
        const idx = col ? col.fotos.findIndex((f) => f.id === visorAdmin.fotoId) : -1;
        if (idx < 0) return null;
        return <div className="t-oscuro adm-visor"><Visor admin fotos={col.fotos} indice={idx} onCambiar={(i) => setVisorAdmin({ colId: col.id, fotoId: col.fotos[i].id })} onCerrar={() => setVisorAdmin(null)} /></div>;
      })()}

      {compartir && (() => {
        const c = colecciones.find((x) => x.id === compartir);
        if (!c) return null;
        const url = `${window.location.origin}${window.location.pathname}#/g/${c.id}`;
        const copiar = async () => { try { await navigator.clipboard.writeText(url); setCopiado(true); } catch (err) { /* sin permiso */ } };
        return (
          <Modal titulo="Compartir galería" onClose={() => setCompartir(null)}>
            <p className="sub" style={{ marginBottom: 12 }}>{c.publica ? 'Cualquiera con este enlace podrá ver la galería.' : 'Esta galería está en privado: actívala como “Público” para que el enlace funcione.'}</p>
            <input type="text" readOnly value={url} onFocus={(e) => e.target.select()} />
            <small className="hint">Aviso: por ahora los datos viven solo en este navegador. Para que el enlace abra en el celular del cliente hay que conectar un hosting con base de datos (siguiente paso).</small>
            <div className="modal-actions">
              <a className="btn" href={`https://wa.me/?text=${encodeURIComponent(`${c.nombre} ${url}`)}`} target="_blank" rel="noreferrer">WhatsApp</a>
              <a className="btn" href={`mailto:?subject=${encodeURIComponent(c.nombre)}&body=${encodeURIComponent(url)}`}>Correo</a>
              <button className="btn primary" onClick={copiar}>{copiado ? '¡Copiado!' : 'Copiar enlace'}</button>
            </div>
          </Modal>
        );
      })()}

      {modalNueva && (
        <Modal titulo="Nueva colección" onClose={() => setModalNueva(false)}>
          <input
            autoFocus
            type="text"
            placeholder="Ej. Boda Carlos"
            value={nombreNueva}
            onChange={(e) => setNombreNueva(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && crearColeccion()}
          />
          <div className="modal-actions">
            <button className="btn" onClick={() => setModalNueva(false)}>Cancelar</button>
            <button className="btn primary" onClick={crearColeccion}>Crear</button>
          </div>
        </Modal>
      )}

      {aBorrar && (
        <Modal titulo="Eliminar colección" onClose={() => setABorrar(null)}>
          <p className="sub">Se borrará “{aBorrar.nombre}” con sus {aBorrar.fotos.length} fotos y toda la actividad de los clientes. Esta acción no se puede deshacer.</p>
          <div className="modal-actions">
            <button className="btn" onClick={() => setABorrar(null)}>Cancelar</button>
            <button className="btn danger-solid" onClick={() => borrarColeccion(aBorrar.id)}>Eliminar</button>
          </div>
        </Modal>
      )}
    </div>
  );
}

/* ============================================================
   ESTILOS (adaptativo: sidebar en PC, barra inferior en móvil)
   ============================================================ */
const CSS = `
.app, .app * { box-sizing: border-box; }
.app {
  --bg:#f6f7f9; --panel:#ffffff; --line:#e5e7eb; --text:#0f172a; --muted:#64748b;
  display:flex; width:100%; height:100vh; height:100dvh; overflow:hidden; margin:0;
  background:var(--bg); color:var(--text);
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif; font-size:14px;
}
.app button, .app input, .app textarea { font-family:inherit; }

/* Sidebar */
.sidebar { width:248px; flex-shrink:0; background:var(--panel); border-right:1px solid var(--line); display:flex; flex-direction:column; padding:20px 12px; }
.brand { display:flex; align-items:center; gap:10px; padding:4px 10px 22px; font-weight:600; font-size:15px; }
.brand-logo { width:32px; height:32px; border-radius:9px; background:var(--text); color:var(--panel); display:grid; place-items:center; }
.nav { display:flex; flex-direction:column; gap:2px; flex:1; }
.nav-btn { position:relative; display:flex; align-items:center; gap:10px; padding:10px 12px; border:0; border-radius:8px; background:transparent; color:var(--muted); font-size:14px; cursor:pointer; text-align:left; width:100%; }
.nav-btn:hover { background:var(--bg); }
.nav-btn.on { background:var(--bg); color:var(--text); font-weight:600; }
.nav-btn.view-client { margin-top:14px; background:color-mix(in srgb, var(--accent) 12%, transparent); color:var(--accent); font-weight:600; }
.badge { margin-left:auto; background:var(--accent); color:#fff; font-size:11px; min-width:18px; height:18px; padding:0 5px; border-radius:9px; display:grid; place-items:center; }
.side-foot { padding:14px 10px 0; border-top:1px solid var(--line); font-size:12px; color:var(--muted); }

/* Contenido: único scroll */
.main { flex:1; min-width:0; height:100%; overflow-y:auto; overflow-x:hidden; }
.page { max-width:1200px; margin:0 auto; padding:32px clamp(16px,4vw,40px) 48px; }
.page-head { display:flex; justify-content:space-between; align-items:flex-end; gap:16px; flex-wrap:wrap; margin-bottom:24px; }
.title { font-size:26px; font-weight:600; letter-spacing:-.02em; margin:0 0 4px; display:flex; align-items:center; gap:12px; flex-wrap:wrap; }
.sub { color:var(--muted); font-size:14px; margin:0; line-height:1.5; }
.live { display:inline-flex; align-items:center; gap:6px; font-size:12px; font-weight:500; color:#059669; background:#d1fae5; padding:3px 10px; border-radius:999px; }
.live i { width:7px; height:7px; border-radius:50%; background:#10b981; animation:pulso 1.6s infinite; }
@keyframes pulso { 50% { opacity:.3; } }

/* Botones */
.btn { display:inline-flex; align-items:center; gap:8px; padding:9px 16px; border-radius:8px; border:1px solid var(--line); background:var(--panel); color:var(--text); font-size:13.5px; font-weight:500; cursor:pointer; }
.btn:hover:not(:disabled) { filter:brightness(.97); }
.btn:disabled { opacity:.45; cursor:default; }
.btn.primary { background:var(--accent); border-color:var(--accent); color:#fff; }
.btn.dark { background:var(--text); border-color:var(--text); color:var(--panel); }
.btn.danger-solid { background:#dc2626; border-color:#dc2626; color:#fff; }
.icon-btn { width:34px; height:34px; border-radius:8px; border:1px solid var(--line); background:var(--panel); color:var(--muted); display:inline-grid; place-items:center; cursor:pointer; flex-shrink:0; }
.icon-btn.danger:hover { color:#dc2626; border-color:#fecaca; }
.link { background:none; border:0; padding:0; color:var(--accent); cursor:pointer; font-size:inherit; font-weight:600; }

/* Estadísticas y tarjetas */
.stats { display:grid; grid-template-columns:repeat(auto-fit,minmax(140px,1fr)); gap:12px; margin-bottom:24px; }
.stat { background:var(--panel); border:1px solid var(--line); border-radius:12px; padding:16px; }
.stat b { display:block; font-size:24px; font-weight:600; letter-spacing:-.02em; }
.stat span { font-size:12px; color:var(--muted); }
.cards { display:grid; grid-template-columns:repeat(auto-fill,minmax(250px,1fr)); gap:20px; }
.card { background:var(--panel); border:1px solid var(--line); border-radius:14px; overflow:hidden; cursor:pointer; transition:transform .15s, box-shadow .15s; }
.card:hover { transform:translateY(-2px); box-shadow:0 8px 24px rgba(15,23,42,.08); }
.card-cover { aspect-ratio:4/3; background:var(--line); overflow:hidden; }
.card-cover img { width:100%; height:100%; object-fit:cover; display:block; }
.empty-cover { width:100%; height:100%; display:grid; place-items:center; color:var(--muted); }
.card-body { padding:14px 16px; display:flex; justify-content:space-between; align-items:center; gap:10px; }
.card-body h4 { margin:0 0 2px; font-size:14px; font-weight:600; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.card-body span { font-size:12px; color:var(--muted); }

/* Fotos del admin */
.photos { display:grid; grid-template-columns:repeat(auto-fill,minmax(150px,1fr)); gap:12px; }
.ph { position:relative; aspect-ratio:1; border-radius:10px; overflow:hidden; background:var(--line); }
.ph img { width:100%; height:100%; object-fit:cover; display:block; }
.ph-actions { position:absolute; top:6px; right:6px; display:flex; gap:4px; }
@media (hover:hover) { .ph-actions { opacity:0; transition:opacity .15s; } .ph:hover .ph-actions { opacity:1; } }
.mini { width:28px; height:28px; border:0; border-radius:7px; background:rgba(15,23,42,.72); color:#fff; display:grid; place-items:center; cursor:pointer; }
.ph-meta { position:absolute; left:0; right:0; bottom:0; display:flex; gap:12px; padding:18px 8px 6px; color:#fff; font-size:11px; background:linear-gradient(transparent,rgba(0,0,0,.65)); }
.ph-meta span { display:inline-flex; align-items:center; gap:4px; }
.dropzone { border:1.5px dashed var(--line); border-radius:14px; padding:48px 20px; text-align:center; color:var(--muted); display:flex; flex-direction:column; align-items:center; gap:8px; }
.dropzone p { margin:0; max-width:380px; line-height:1.5; }

/* Paneles y formularios */
.panel { background:var(--panel); border:1px solid var(--line); border-radius:14px; padding:22px; }
.split { display:grid; grid-template-columns:minmax(0,1fr) minmax(0,1.2fr); gap:20px; align-items:start; }
.field { margin-bottom:18px; }
.field label, .lbl { display:flex; justify-content:space-between; gap:8px; font-size:13px; font-weight:500; margin-bottom:8px; }
.field label b { color:var(--muted); font-weight:500; }
.hint { display:block; margin-top:6px; color:var(--muted); font-size:12px; }
.app input[type=text], .app input[type=email], .app textarea { width:100%; padding:10px 12px; border-radius:8px; border:1px solid var(--line); background:var(--panel); color:var(--text); font-size:14px; outline:none; }
.app input[type=text]:focus, .app input[type=email]:focus, .app textarea:focus { border-color:var(--accent); }
.app input[type=range] { width:100%; accent-color:var(--accent); }
.app textarea { resize:vertical; }
.preview { position:relative; aspect-ratio:4/3; border-radius:12px; overflow:hidden; background:var(--line); }
.preview img { width:100%; height:100%; object-fit:cover; display:block; }
.seg { display:inline-flex; flex-wrap:wrap; gap:2px; padding:3px; border:1px solid var(--line); border-radius:9px; background:var(--bg); }
.seg button { border:0; background:transparent; color:var(--muted); padding:7px 14px; border-radius:7px; font-size:13px; cursor:pointer; }
.seg button.on { background:var(--panel); color:var(--text); font-weight:600; box-shadow:0 1px 2px rgba(0,0,0,.08); }
.swatches { display:flex; gap:10px; flex-wrap:wrap; }
.swatches button { width:30px; height:30px; border-radius:50%; border:2px solid var(--panel); cursor:pointer; box-shadow:0 0 0 1px var(--line); }
.swatches button.on { box-shadow:0 0 0 2px var(--text); }

/* Marca de agua (malla diagonal) */
.wm-layer { position:absolute; left:50%; top:50%; width:200%; height:200%; background-repeat:repeat; pointer-events:none; }

/* Notificaciones */
.notif { position:relative; display:flex; align-items:flex-start; gap:14px; padding:16px 0; border-bottom:1px solid var(--line); }
.notif:last-child { border-bottom:0; }
.notif img { width:54px; height:54px; object-fit:cover; border-radius:8px; flex-shrink:0; }
.notif-body { flex:1; min-width:0; }
.notif-body p { margin:0 0 4px; line-height:1.45; }
.notif-body blockquote { margin:6px 0; padding:8px 12px; background:var(--bg); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; font-size:13px; }
.notif-body small { color:var(--muted); font-size:12px; word-break:break-all; }
.tipo { width:28px; height:28px; border-radius:50%; display:grid; place-items:center; flex-shrink:0; }
.tipo.like { background:#ffe4e6; color:#f43f5e; }
.tipo.nota { background:#e0f2fe; color:#0284c7; }
.dot { position:absolute; top:18px; right:-2px; width:8px; height:8px; border-radius:50%; background:var(--accent); }

/* Modal */
.modal-bg { position:fixed; inset:0; z-index:100; background:rgba(15,23,42,.5); display:grid; place-items:center; padding:16px; }
.modal { width:100%; max-width:420px; background:var(--panel); color:var(--text); border-radius:14px; padding:24px; }
.modal h3 { margin:0 0 14px; font-size:18px; }
.modal-actions { display:flex; justify-content:flex-end; gap:10px; margin-top:20px; }

/* Vista del cliente */
.preview-banner { position:sticky; top:0; z-index:20; display:flex; justify-content:space-between; align-items:center; gap:12px; padding:9px clamp(14px,3vw,28px); background:#1e293b; color:#fff; font-size:13px; }
.preview-banner button { display:inline-flex; align-items:center; gap:6px; border:0; background:var(--accent); color:#fff; padding:6px 12px; border-radius:7px; cursor:pointer; font-size:13px; }
.c-top { display:flex; justify-content:space-between; align-items:center; padding:16px clamp(14px,3vw,32px); }
.c-brand { display:inline-flex; align-items:center; gap:8px; font-weight:600; letter-spacing:.04em; font-size:13px; }
.c-hero { text-align:center; padding:28px 16px 32px; }
.c-hero h1 { font-size:clamp(26px,5vw,44px); font-weight:300; margin:0 0 8px; letter-spacing:-.01em; }
.c-hero p { margin:0 0 10px; color:var(--muted); font-size:15px; }
.c-hero small { color:var(--muted); font-size:12.5px; }
.gate { width:min(92%,400px); margin:clamp(24px,8vh,80px) auto; padding:32px 28px; background:var(--panel); border:1px solid var(--line); border-radius:16px; text-align:center; display:flex; flex-direction:column; gap:12px; user-select:auto; -webkit-user-select:auto; }
.gate h2 { margin:0; font-size:24px; font-weight:500; }
.gate p { margin:0 0 6px; color:var(--muted); }
.gate-ico { width:46px; height:46px; margin:0 auto 4px; border-radius:50%; display:grid; place-items:center; background:color-mix(in srgb, var(--accent) 15%, transparent); color:var(--accent); }
.err { color:#ef4444; font-size:12.5px; text-align:left; }
.gallery { padding:0 clamp(14px,3vw,32px) 48px; max-width:1500px; margin:0 auto; }
.gallery.grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(min(100%,280px),1fr)); gap:18px; }
.gallery.masonry { column-width:280px; column-gap:18px; }
.gallery.masonry .shot { break-inside:avoid; margin-bottom:18px; }
.shot { background:var(--panel); border:1px solid var(--line); border-radius:10px; overflow:hidden; }
.shot-img { position:relative; overflow:hidden; }
.shot-img img { display:block; width:100%; height:100%; object-fit:cover; pointer-events:none; user-select:none; -webkit-user-drag:none; }
.gallery.grid .shot-img { aspect-ratio:4/3; background:var(--bg); }
.gallery.grid .shot-img.f-vertical img { object-fit:contain; }
.gallery.masonry .shot-img img { height:auto; }
.shield { position:absolute; inset:0; }
.forma { margin-left:auto; opacity:.9; }
.banner { display:flex; align-items:center; gap:10px; flex-wrap:wrap; padding:12px 16px; margin-bottom:16px; border-radius:10px; border:1px solid var(--line); background:color-mix(in srgb, var(--accent) 10%, var(--panel)); font-size:13px; }
.banner.warn { background:#fef3c7; color:#92400e; border-color:#fde68a; }
.spin { width:14px; height:14px; border-radius:50%; border:2px solid var(--line); border-top-color:var(--accent); animation:giro .8s linear infinite; flex-shrink:0; }
@keyframes giro { to { transform:rotate(360deg); } }
.shot-bar { display:flex; justify-content:space-between; align-items:center; padding:8px 8px 8px 14px; }
.shot-num { font-size:12px; color:var(--muted); }
.act { display:inline-flex; align-items:center; gap:6px; border:0; background:transparent; color:var(--muted); padding:7px 9px; border-radius:8px; cursor:pointer; font-size:13px; font-weight:600; }
.act:hover { background:var(--bg); }
.act.liked { color:#f43f5e; }
.note-box { padding:0 14px 14px; user-select:auto; -webkit-user-select:auto; }
.my-note { margin:0 0 8px; padding:8px 12px; background:var(--bg); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; font-size:13px; }
.cwrap textarea, .cwrap .gate input { background:var(--bg); color:var(--text); border-color:var(--line); }

/* Responsive: móvil / tablet */
@media (max-width: 860px) {
  .app { flex-direction:column; }
  .main, .cwrap { order:1; flex:1; min-height:0; }
  .sidebar { order:2; width:100%; flex-direction:row; padding:6px 6px calc(6px + env(safe-area-inset-bottom)); border-right:0; border-top:1px solid var(--line); }
  .brand, .side-foot { display:none; }
  .nav { flex-direction:row; gap:0; }
  .nav-btn, .nav-btn.view-client { flex:1; flex-direction:column; justify-content:center; align-items:center; gap:3px; padding:8px 2px; margin:0; font-size:10.5px; text-align:center; background:transparent; }
  .nav-btn.on { background:var(--bg); }
  .nav-btn .badge { position:absolute; top:2px; left:calc(50% + 6px); margin:0; }
  .split { grid-template-columns:minmax(0,1fr); }
  .page { padding-top:22px; }
  .title { font-size:22px; }
}
@media (max-width: 480px) {
  .cards { grid-template-columns:repeat(auto-fill,minmax(150px,1fr)); gap:12px; }
  .photos { grid-template-columns:repeat(auto-fill,minmax(110px,1fr)); gap:8px; }
}

/* ===== Visor de fotos ===== */
.visor { position:absolute; inset:0; z-index:200; display:flex; flex-direction:column; background:#07090d; color:#fff; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif; user-select:none; -webkit-user-select:none; }
.vz-bar { display:flex; justify-content:space-between; align-items:center; gap:12px; padding:10px clamp(12px,2vw,20px); border-bottom:1px solid rgba(255,255,255,.08); }
.vz-name { min-width:0; display:flex; flex-direction:column; gap:2px; }
.vz-name b { font-size:14px; font-weight:600; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.vz-name span { font-size:12px; color:#94a3b8; }
.vz-tools { display:flex; align-items:center; gap:6px; flex-shrink:0; }
.vz-btn { display:inline-flex; align-items:center; justify-content:center; gap:6px; min-width:36px; height:36px; padding:0 9px; border:0; border-radius:8px; background:rgba(255,255,255,.08); color:#fff; font-size:13px; cursor:pointer; }
.vz-btn:hover { background:rgba(255,255,255,.16); }
.vz-btn.txt { min-width:56px; font-variant-numeric:tabular-nums; }
.vz-btn.on { background:var(--accent,#2563eb); }
.vz-btn.liked { color:#fb7185; }
.vz-body { flex:1; min-height:0; display:flex; }
.vz-main { position:relative; flex:1; min-width:0; }
.vz-stage { position:absolute; inset:0; overflow:hidden; display:grid; place-items:center; touch-action:none; }
.vz-stage img { max-width:100%; max-height:100%; object-fit:contain; pointer-events:none; user-select:none; -webkit-user-drag:none; will-change:transform; }
.vz-nav { position:absolute; top:50%; transform:translateY(-50%); width:44px; height:44px; border:0; border-radius:50%; background:rgba(0,0,0,.5); color:#fff; display:grid; place-items:center; cursor:pointer; z-index:3; }
.vz-nav:hover { background:rgba(0,0,0,.8); }
.vz-nav.l { left:12px; } .vz-nav.r { right:12px; }
.vz-side { width:320px; flex-shrink:0; overflow-y:auto; padding:18px 20px 28px; background:#10141c; border-left:1px solid rgba(255,255,255,.08); user-select:text; -webkit-user-select:text; }
.vz-side h4 { margin:0 0 10px; font-size:11px; letter-spacing:.1em; text-transform:uppercase; color:#94a3b8; }
.vz-side h4:not(:first-child) { margin-top:24px; }
.vz-side dl { margin:0; }
.vz-side dl div { display:flex; justify-content:space-between; gap:14px; padding:8px 0; border-bottom:1px solid rgba(255,255,255,.06); font-size:13px; }
.vz-side dt { color:#94a3b8; flex-shrink:0; }
.vz-side dd { margin:0; text-align:right; word-break:break-word; }
.vz-hint { margin:10px 0 0; font-size:12px; line-height:1.5; color:#94a3b8; }
.vz-act { margin:0 0 8px; font-size:13px; line-height:1.45; }
.vz-act small { color:#94a3b8; margin-left:4px; }
.vz-act svg { color:#fb7185; vertical-align:-2px; }
.vz-act.nota svg { color:#38bdf8; }
@media (max-width:760px) {
  .vz-body { flex-direction:column; }
  .vz-side { width:100%; max-height:42%; border-left:0; border-top:1px solid rgba(255,255,255,.08); }
  .vz-btn.txt { display:none; }
}

/* ===== Panel de diseño con previsualización ===== */
.app { position:relative; }
.page.wide { max-width:1600px; }
.dsg { display:grid; grid-template-columns:minmax(290px,370px) minmax(0,1fr); gap:20px; align-items:start; }
.dsg-ctrl { max-height:calc(100dvh - 150px); overflow-y:auto; }
.dsg-view { position:sticky; top:0; }
.dsg-bar { display:flex; justify-content:space-between; flex-wrap:wrap; gap:10px; margin-bottom:14px; }
.frame { height:min(760px,calc(100dvh - 230px)); min-height:420px; margin:0 auto; border:1px solid var(--line); border-radius:12px; overflow:hidden; background:var(--bg); }
.frame.movil { width:390px; max-width:100%; border:7px solid #1e293b; border-radius:34px; }
.grp { margin:22px 0 12px; padding-top:16px; border-top:1px solid var(--line); font-size:11px; letter-spacing:.1em; text-transform:uppercase; color:var(--muted); }
.grp:first-child { margin-top:0; padding-top:0; border-top:0; }
.swatches input[type=color] { width:30px; height:30px; padding:0; border:0; border-radius:50%; background:none; cursor:pointer; }
.ph { cursor:pointer; }
.ph-name { position:absolute; left:8px; right:70px; top:8px; font-size:11px; color:#fff; text-shadow:0 1px 3px #000; overflow:hidden; white-space:nowrap; text-overflow:ellipsis; }
.notif img { cursor:pointer; }
.file { display:flex; align-items:center; gap:6px; margin:2px 0 4px; font-size:13px; color:var(--muted); }
.file .link { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }

/* ===== Vista del cliente: temas, portada y galería ===== */
.cwrap { position:relative; flex:1; min-width:0; height:100%; overflow:hidden; container-type:size; background:var(--bg); color:var(--text); }
.cwrap .client { height:100%; overflow-y:auto; overflow-x:hidden; -webkit-touch-callout:none; user-select:none; -webkit-user-select:none; }
.t-claro { --bg:#ffffff; --panel:#f8fafc; --line:#e2e8f0; --text:#0f172a; --muted:#64748b; }
.t-marfil { --bg:#faf6ef; --panel:#f2ece1; --line:#e3d9c6; --text:#2b2118; --muted:#8a7a66; }
.t-gris { --bg:#e9ebee; --panel:#f4f5f7; --line:#d3d7dd; --text:#1b2430; --muted:#6b7684; }
.t-oscuro { --bg:#0b0f17; --panel:#131a26; --line:#243044; --text:#f1f5f9; --muted:#94a3b8; }
.t-negro { --bg:#000000; --panel:#0d0d0d; --line:#222222; --text:#f5f5f5; --muted:#8a8a8a; }
.hero-full { position:relative; height:72cqh; min-height:340px; overflow:hidden; display:grid; place-items:end center; text-align:center; color:#fff; background:#111; }
.hero-full > img { position:absolute; inset:0; width:100%; height:100%; object-fit:cover; pointer-events:none; }
.hero-full::after { content:""; position:absolute; inset:0; background:linear-gradient(transparent 35%, rgba(0,0,0,.72)); pointer-events:none; }
.hero-txt { position:relative; z-index:2; padding:0 20px 7cqh; }
.hero-txt h1 { margin:0 0 6px; font-size:clamp(30px,6vw,62px); font-weight:300; letter-spacing:-.01em; }
.hero-txt p { margin:0 0 20px; opacity:.85; }
.hero-btn { border:1px solid rgba(255,255,255,.75); background:transparent; color:#fff; padding:10px 28px; font-size:12px; letter-spacing:.16em; text-transform:uppercase; cursor:pointer; }
.hero-btn:hover { background:rgba(255,255,255,.14); }
.hero-split { display:grid; grid-template-columns:1fr 1.25fr; gap:clamp(20px,4vw,56px); align-items:center; max-width:1300px; margin:0 auto; padding:12px clamp(14px,3vw,32px) 36px; }
.hero-split h1 { margin:0 0 8px; font-size:clamp(26px,4.5vw,46px); font-weight:300; }
.hero-split p { margin:0 0 12px; color:var(--muted); }
.hero-split small { color:var(--muted); }
.hs-img { position:relative; aspect-ratio:4/3; overflow:hidden; border-radius:var(--rad); background:var(--panel); }
.hs-img img { width:100%; height:100%; object-fit:cover; display:block; pointer-events:none; }
@container (max-width:720px) { .hero-split { grid-template-columns:1fr; } }
.c-hero.min { padding:8px 16px 20px; }
.c-hero.min h1 { font-size:clamp(20px,3.5vw,28px); }
.gallery.grid { grid-template-columns:repeat(auto-fill,minmax(min(100%,var(--col)),1fr)); gap:var(--gap); }
.gallery.masonry { column-width:var(--col); column-gap:var(--gap); }
.gallery.masonry .shot { margin-bottom:var(--gap); }
.gallery.single { display:flex; flex-direction:column; gap:var(--gap); max-width:min(100%,920px); }
.gallery.single .shot-img img { height:auto; }
.shot { border-radius:var(--rad); }
.shot-img { cursor:zoom-in; }
.shot-num { min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }


/* ===== Visor estilo Pixieset (usa el tema, tipografía y acento de la galería) ===== */
.visor { background:var(--bg); color:var(--text); font-family:inherit; }
.adm-visor { position:absolute; inset:0; z-index:200; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif; }
.vz-bar { border-bottom:0; padding:14px clamp(14px,3vw,32px); }
.vz-name b { font-weight:400; font-size:15px; letter-spacing:.05em; }
.vz-name span { color:var(--muted); letter-spacing:.12em; font-size:11px; }
.vz-btn { background:transparent; color:var(--muted); border-radius:50%; min-width:38px; height:38px; }
.vz-btn.txt { border-radius:19px; font-size:12px; }
.vz-btn:hover { background:var(--panel); color:var(--text); }
.vz-btn.on { background:var(--accent,#2563eb); color:#fff; }
.vz-btn.liked { color:var(--accent,#f43f5e); }
.vz-stage { display:block; padding:clamp(6px,2vw,28px); }
.vz-stage img { width:100%; height:100%; max-width:none; max-height:none; object-fit:contain; }
.vz-nav { background:var(--panel); color:var(--text); border:1px solid var(--line); box-shadow:0 2px 10px rgba(0,0,0,.18); width:42px; height:42px; }
.vz-nav:hover { background:var(--accent,#2563eb); color:#fff; border-color:transparent; }
.vz-side { background:var(--panel); border-left:1px solid var(--line); }
.vz-side h4, .vz-side dt, .vz-hint, .vz-act small { color:var(--muted); }
.vz-side dl div { border-bottom-color:var(--line); }

/* ===== Público / compartir ===== */
.card-cover { position:relative; }
.pub { position:absolute; top:10px; left:10px; z-index:2; display:inline-flex; align-items:center; gap:7px; padding:5px 11px 5px 9px; border:0; border-radius:999px; background:rgba(15,23,42,.78); color:#fff; font-size:12px; font-weight:600; cursor:pointer; backdrop-filter:blur(6px); }
.pub i { width:8px; height:8px; border-radius:50%; background:#94a3b8; }
.pub.on i { background:#22c55e; box-shadow:0 0 0 3px rgba(34,197,94,.3); }
.card-acts { display:flex; gap:6px; flex-shrink:0; }
.app select { width:100%; padding:10px 12px; border-radius:8px; border:1px solid var(--line); background:var(--panel); color:var(--text); font-size:14px; }
.modal a.btn { text-decoration:none; }


/* ===== Visor: corazón y comentarios abajo ===== */
.vz-foot { position:relative; display:grid; grid-template-columns:1fr auto 1fr; align-items:center; gap:14px; padding:12px clamp(14px,3vw,32px) calc(16px + env(safe-area-inset-bottom,0px)); }
.vz-heart { display:inline-flex; align-items:center; gap:9px; height:48px; padding:0 24px; border-radius:999px; border:1px solid var(--line); background:var(--panel); color:var(--text); font-size:15px; cursor:pointer; }
.vz-heart.liked { background:var(--accent,#f43f5e); border-color:var(--accent,#f43f5e); color:#fff; }
.vz-cmt { justify-self:start; display:inline-flex; align-items:center; gap:8px; height:40px; padding:0 16px; border-radius:999px; border:1px solid var(--line); background:transparent; color:var(--muted); font-size:13px; cursor:pointer; }
.vz-cmt:hover, .vz-cmt.on { color:var(--text); background:var(--panel); }
.vz-note { position:absolute; bottom:100%; left:50%; transform:translateX(-50%); z-index:5; width:min(92%,420px); padding:14px; border-radius:14px; background:var(--panel); border:1px solid var(--line); box-shadow:0 12px 40px rgba(0,0,0,.3); user-select:text; -webkit-user-select:text; }
.vz-note .btn { margin-top:8px; }
@media (max-width:520px) { .vz-cmt { font-size:0; gap:0; padding:0 12px; } .vz-cmt svg { font-size:14px; } }

/* ===== Modo oscuro del panel del fotógrafo ===== */
.app.adm-dark { --bg:#0b0f17; --panel:#131a26; --line:#243044; --text:#f1f5f9; --muted:#94a3b8; color-scheme:dark; }
.app.adm-dark .tipo.like { background:#4c0519; }
.app.adm-dark .tipo.nota { background:#0c4a6e; }
@media (min-width:861px) { .nav .theme-toggle { margin-top:auto; } }


/* ===== Logo ProofStudio ===== */
.logo { display:inline-block; background-color:currentColor; -webkit-mask-repeat:no-repeat; mask-repeat:no-repeat; -webkit-mask-position:center; mask-position:center; -webkit-mask-size:contain; mask-size:contain; max-width:100%; }
.brand { justify-content:center; padding:6px 10px 24px; color:#222d3b; }
.app.adm-dark .brand, .app.adm-dark .m-brand { color:#f1f5f9; }
.m-brand { display:none; color:#222d3b; justify-content:center; padding:16px 0 0; }
@media (max-width:860px) { .m-brand { display:flex; } }


/* ===== Cliente: acceso minimalista con los colores de la galería + logo ===== */
.c-logo { color:var(--text); display:flex; justify-content:center; margin-bottom:6px; }
.c-foot { display:flex; flex-direction:column; align-items:center; gap:10px; padding:44px 16px calc(36px + env(safe-area-inset-bottom,0px)); color:var(--muted); font-size:10.5px; letter-spacing:.16em; text-transform:uppercase; }
.cwrap .gate { width:min(92%,360px); padding:8px 0; gap:20px; background:transparent; border:0; }
.cwrap .gate h2 { font-size:clamp(26px,5vw,38px); font-weight:300; letter-spacing:-.01em; color:var(--text); }
.cwrap .gate p { color:var(--muted); }
.cwrap .gate input { padding:12px 2px; border:0; border-bottom:1px solid var(--line); border-radius:0; background:transparent; color:var(--text); font-size:15px; text-align:center; }
.cwrap .gate input::placeholder { color:var(--muted); }
.cwrap .gate input:focus { border-bottom-color:var(--accent); }
.cwrap .gate input:-webkit-autofill { -webkit-text-fill-color:var(--text); box-shadow:0 0 0 1000px var(--bg) inset; caret-color:var(--text); }
.cwrap .gate .btn.primary { margin-top:6px; padding:14px; border-radius:var(--rad); font-size:12px; letter-spacing:.16em; text-transform:uppercase; }

`;